function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'TextEditor' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with TextEditor() and no arguments.';
  if (operations.length - 1 > 20000) return 'At most 2 * 10^4 calls after the constructor.';
  for (let i = 1; i < operations.length; i++) {
    const op = operations[i], a = args[i];
    if (!['addText', 'deleteText', 'cursorLeft', 'cursorRight'].includes(op)) return 'Only addText, deleteText, cursorLeft and cursorRight can follow the constructor.';
    if (!Array.isArray(a) || a.length !== 1) return 'Each call takes exactly one argument.';
    if (op === 'addText') {
      if (typeof a[0] !== 'string' || a[0].length < 1 || a[0].length > 40 || !/^[a-z]+$/.test(a[0])) return 'addText takes 1 to 40 lowercase letters.';
    } else if (!Number.isInteger(a[0]) || a[0] < 1 || a[0] > 40) return 'k is between 1 and 40.';
  }
  return null;
}

