class TextEditor {
  constructor() {
    this.left = [];
    this.right = [];
  }

  addText(text) {
    for (const ch of text) {
      this.left.push(ch);
    }
  }

  deleteText(k) {
    const removed = Math.min(k, this.left.length);
    for (let i = 0; i < removed; i++) {
      this.left.pop();
    }
    return removed;
  }

  cursorLeft(k) {
    for (let i = 0; i < k && this.left.length > 0; i++) {
      this.right.push(this.left.pop());
    }
    return this.left.slice(-10).join('');
  }

  cursorRight(k) {
    for (let i = 0; i < k && this.right.length > 0; i++) {
      this.left.push(this.right.pop());
    }
    return this.left.slice(-10).join('');
  }
}

