class TextEditor {
  // Keep the whole text as one string and the cursor as an index into it.
  constructor() {
    this.text = '';
    this.cursor = 0;
  }
  addText(text) {
    this.text = this.text.slice(0, this.cursor) + text + this.text.slice(this.cursor);
    this.cursor += text.length;
  }
  deleteText(k) {
    const gone = Math.min(k, this.cursor);
    this.text = this.text.slice(0, this.cursor - gone) + this.text.slice(this.cursor);
    this.cursor -= gone;
    return gone;
  }
  cursorLeft(k) {
    this.cursor = Math.max(0, this.cursor - k);
    return this.text.slice(Math.max(0, this.cursor - 10), this.cursor);
  }
  cursorRight(k) {
    this.cursor = Math.min(this.text.length, this.cursor + k);
    return this.text.slice(Math.max(0, this.cursor - 10), this.cursor);
  }
}

