function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const alphabet = size === 'large' ? 'abcdefghijklmnopqrstuvwxyz' : 'abc';
  const calls = size === 'large' ? 499 : pick(1, 12);
  const operations = ['TextEditor'];
  const args = [[]];
  for (let i = 0; i < calls; i++) {
    const r = rand();
    const k = size === 'large' ? pick(1, 40) : pick(1, rand() < 0.7 ? 6 : 40);
    if (r < 0.35) {
      const length = size === 'large' ? pick(1, 40) : pick(1, rand() < 0.8 ? 4 : 40);
      operations.push('addText');
      args.push([Array.from({ length }, () => alphabet[Math.floor(rand() * alphabet.length)]).join('')]);
    } else if (r < 0.55) {
      operations.push('deleteText');
      args.push([k]);
    } else if (r < 0.8) {
      operations.push('cursorLeft');
      args.push([k]);
    } else {
      operations.push('cursorRight');
      args.push([k]);
    }
  }
  return [operations, args];
}
